// Ported from the public AIcss React source.
// Source: https://www.aicss.dev/components/text-response
"use client"

import styles from "./text-response.module.css";
import { useState, type ReactNode } from "react";

/** Where a model's answer stands. Anything but "complete" says so on screen. */
export type AiResponseStatus = "complete" | "streaming" | "stopped" | "failed" | "refused";

/** What a refusal tells the person: the topic it will not cover, and what they can do instead. */
export interface AiRefusal {
  topic: string;
  alternative: string;
}

export function TextResponse({
  children,
  status = "complete",
  label = "AI-generated",
  refusal,
  onRetry,
  onFeedback,
}: {
  children?: ReactNode;
  status?: AiResponseStatus;
  /** The visible marker that a model wrote this. Keep it on every answer. */
  label?: string;
  refusal?: AiRefusal;
  onRetry?: () => void;
  /** Where a rating goes. Without it no rating buttons show, because a rating must reach someone. */
  onFeedback?: (rating: "helpful" | "not-helpful") => void;
}) {
  const [rated, setRated] = useState<"helpful" | "not-helpful" | null>(null);

  const rate = (rating: "helpful" | "not-helpful") => {
    setRated(rating);
    onFeedback?.(rating);
  };

  return (
    <div className={styles.response} data-status={status} aria-busy={status === "streaming" || undefined}>
      <p className={styles.aiLabel}>{label}</p>
      {status === "refused" ? (
        <div className={styles.notice}>
          <p>I can&apos;t help with {refusal?.topic ?? "this request"}.</p>
          {refusal?.alternative && <p className={styles.noticeHint}>{refusal.alternative}</p>}
        </div>
      ) : (
        <div className={styles.prose}>{children}</div>
      )}
      {status === "stopped" && (
        <p className={styles.notice} role="status">
          Stopped. The answer above is incomplete.
        </p>
      )}
      {status === "failed" && (
        <div className={styles.notice} role="alert">
          <p>The answer failed before it finished. Nothing above was changed.</p>
          {onRetry && (
            <button type="button" className={styles.action} onClick={onRetry}>
              Try again
            </button>
          )}
        </div>
      )}
      {status === "complete" && onFeedback && (
        <div className={styles.feedback} role="group" aria-label="Rate this answer">
          {rated ? (
            <p role="status" className={styles.noticeHint}>
              Thanks. Your rating was sent.
            </p>
          ) : (
            <>
              <button type="button" className={styles.action} onClick={() => rate("helpful")}>
                Helpful
              </button>
              <button type="button" className={styles.action} onClick={() => rate("not-helpful")}>
                Not helpful
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

/* Ported from https://www.aicss.dev/components/text-response */
.prose { font-size: 0.875rem; line-height: 1.1875rem; color: var(--foreground); }
.prose p { margin-bottom: 0.625rem; }
.prose p:last-child { margin-bottom: 0; }
.prose code { font-family: ui-monospace, monospace; font-size: 0.78125rem; color: inherit; background: var(--muted); padding: 0.1875rem 0.3125rem 0.0625rem; border-radius: 0.3125rem; }
/* Answer states, the AI label and the rating bar. [BD-1055] */
.response { display: flex; flex-direction: column; gap: 0.5rem; }
.aiLabel { align-self: flex-start; margin: 0; padding: 0.125rem 0.5rem; border-radius: 999rem; font-size: 0.75rem; line-height: 1rem; font-weight: 500; color: var(--ai-label-foreground); background: var(--ai-label); }
.notice { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; margin: 0; padding: 0.5rem 0.75rem; border: 0.0625rem solid var(--border); border-radius: 0.5rem; font-size: 0.875rem; line-height: 1.25rem; color: var(--foreground); }
.notice p { margin: 0; }
.response[data-status="failed"] .notice { border-color: var(--destructive); }
.noticeHint { margin: 0; font-size: 0.875rem; line-height: 1.25rem; color: var(--muted-foreground); }
.feedback { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.action { min-height: 2rem; padding: 0 0.75rem; border: 0.0625rem solid var(--border); border-radius: 0.5rem; background: transparent; font: inherit; font-size: 0.8125rem; color: var(--foreground); cursor: pointer; }
@media (hover: hover) and (pointer: fine) { .action:hover { background: var(--muted); } }
.action:focus-visible { outline: 0.125rem solid var(--ring); outline-offset: 0.125rem; }
